1	/**
2	 * WebSocket Event Bridge
3	 *
4	 * Connects to the bot gateway's `/ws/events` endpoint and feeds incoming
5	 * nia.event envelopes into the same niaEventRouter used by the Daily.co
6	 * app-message bridge.  This allows PearlOS UI tools (notes, YouTube,
7	 * windows, etc.) to work even when there is no active Daily.co room.
8	 *
9	 * Usage:
10	 *   import { startWsEventBridge, stopWsEventBridge } from './wsEventBridge';
11	 *   startWsEventBridge('ws://localhost:4444/ws/events');
12	 *   // later:
13	 *   stopWsEventBridge();
14	 */
15	
16	import { getClientLogger } from '@interface/lib/client-logger';
17	import { isDuplicateEvent } from '@interface/lib/event-dedup';
18	
19	import type { AppMessageEnvelope } from './appMessageBridge';
20	import { routeNiaEvent } from './niaEventRouter';
21	
22	const log = getClientLogger('[ws_event_bridge]');
23	
24	let _ws: WebSocket | null = null;
25	let _url: string | null = null;
26	let _sessionId: string | null = null;
27	let _reconnectTimer: ReturnType<typeof setTimeout> | null = null;
28	let _stopped = false;
29	
30	const RECONNECT_INTERVAL_MS = 3000;
31	const MAX_RECONNECT_INTERVAL_MS = 30000;
32	let _reconnectDelay = RECONNECT_INTERVAL_MS;
33	
34	function isNiaEnvelope(obj: unknown): obj is AppMessageEnvelope {
35	  return (
36	    !!obj &&
37	    typeof obj === 'object' &&
38	    (obj as Record<string, unknown>).kind === 'nia.event' &&
39	    typeof (obj as Record<string, unknown>).event === 'string'
40	  );
41	}
42	
43	function connect(url: string) {
44	  if (_stopped) return;
45	
46	  try {
47	    const ws = new WebSocket(url);
48	
49	    ws.onopen = () => {
50	      log.info('Connected to bot gateway WebSocket', { url, sessionId: _sessionId });
51	      _reconnectDelay = RECONNECT_INTERVAL_MS; // reset backoff
52	      // Send session scoping message if a session ID is set
53	      if (_sessionId) {
54	        try {
55	          ws.send(JSON.stringify({ session_id: _sessionId }));
56	          log.info('Sent session_id to gateway WebSocket', { sessionId: _sessionId });
57	        } catch (err) {
58	          log.warn('Failed to send session_id', { error: String(err) });
59	        }
60	      }
61	    };
62	
63	    ws.onmessage = (ev: MessageEvent) => {
64	      try {
65	        const data = JSON.parse(ev.data);
66	
67	        // Handle keepalive pings from server
68	        if (data.type === 'ping') {
69	          try { ws.send(JSON.stringify({ type: 'pong' })); } catch { /* noop */ }
70	          return;
71	        }
72	
73	        // Filter by sessionUserId if targeted
74	        if (data.targetSessionUserId) {
75	          const currentSessionUserId = sessionStorage.getItem('sessionUserId');
76	          if (currentSessionUserId !== data.targetSessionUserId) {
77	            return; // not for this user
78	          }
79	        }
80	
81	        if (isNiaEnvelope(data)) {
82	          if (!isDuplicateEvent(data.seq, data.ts, data.event)) {
83	            routeNiaEvent(data);
84	          }
85	        }
86	        // Also handle nia.tool_invoke envelopes (pass through to router as-is)
87	        if (data.kind === 'nia.tool_invoke') {
88	          // Tool invocations are handled by the bot process; we just
89	          // observe them for debugging. No routing needed on the frontend.
90	          log.debug('Received tool_invoke via WS', { tool: data.tool_name });
91	        }
92	      } catch {
93	        // Ignore malformed messages
94	      }
95	    };
96	
97	    ws.onclose = () => {
98	      log.info('WebSocket disconnected, scheduling reconnect', {
99	        delay: _reconnectDelay,
100	      });
101	      _ws = null;
102	      scheduleReconnect(url);
103	    };
104	
105	    ws.onerror = (err) => {
106	      log.warn('WebSocket error', { error: String(err) });
107	      // onclose will fire after onerror
108	    };
109	
110	    _ws = ws;
111	  } catch (err) {
112	    log.warn('Failed to create WebSocket', { error: String(err) });
113	    scheduleReconnect(url);
