1	'use client';
2	
3	/**
4	 * OpenClawEventBridge
5	 *
6	 * Listens for nia.event envelopes carrying `openclaw.task.trigger` and
7	 * dispatches the task through the bridge client. This wires the pipecat
8	 * bot's tool call into the client-side streaming pipeline.
9	 *
10	 * Mount this component once (e.g. in the desktop layout) — it renders nothing.
11	 */
12	
13	import { useEffect } from 'react';
14	
15	import { NIA_EVENT_OPENCLAW_TASK } from '@interface/features/DailyCall/events/niaEventRouter';
16	
17	import { triggerOpenClawTask } from '../triggerOpenClawTask';
18	import { OPENCLAW_BRIDGE_EVENTS } from '../events';
19	
20	export function OpenClawEventBridge() {
21	  useEffect(() => {
22	    function handleOpenClawTask(e: Event) {
23	      const detail = (e as CustomEvent).detail;
24	      const prompt: string | undefined =
25	        detail?.payload?.prompt ?? detail?.payload?.task ?? detail?.prompt ?? detail?.task;
26	
27	      if (!prompt) return;
28	
29	      const assistantId: string | undefined =
30	        detail?.payload?.assistantId ?? detail?.assistantId;
31	      const conversationId: string | undefined =
32	        detail?.payload?.conversationId ?? detail?.conversationId;
33	
34	      // Fire-and-forget: stream the task and dispatch completion/failure events
35	      triggerOpenClawTask({ prompt, assistantId, conversationId }).then(
36	        (result) => {
37	          if (result.success) {
38	            window.dispatchEvent(
39	              new CustomEvent(OPENCLAW_BRIDGE_EVENTS.TASK_COMPLETED, {
40	                detail: { response: result.response },
41	              })
42	            );
43	          } else {
44	            window.dispatchEvent(
45	              new CustomEvent(OPENCLAW_BRIDGE_EVENTS.TASK_FAILED, {
46	                detail: { error: result.error },
47	              })
48	            );
49	          }
50	        },
51	        (err) => {
52	          window.dispatchEvent(
53	            new CustomEvent(OPENCLAW_BRIDGE_EVENTS.TASK_FAILED, {
54	              detail: { error: String(err) },
55	            })
56	          );
57	        }
58	      );
59	    }
60	
61	    window.addEventListener(NIA_EVENT_OPENCLAW_TASK, handleOpenClawTask);
62	    return () =>
63	      window.removeEventListener(NIA_EVENT_OPENCLAW_TASK, handleOpenClawTask);
64	  }, []);
65	
66	  return null;
67	}
68

