1	import { NextResponse } from 'next/server';
2	import { promises as fs } from 'fs';
3	
4	const TASKS_FILE = '/tmp/pearlos-tasks.json';
5	
6	/** How long (ms) to keep approved/complete tasks before auto-removing them */
7	const AUTO_CLEAR_DELAY_MS = 2 * 60 * 1000; // 2 minutes after approval
8	
9	export type TaskStatus = 'pending' | 'running' | 'complete' | 'failed';
10	export type TaskApprovalStatus = 'pending' | 'approved' | 'rework';
11	
12	export interface TaskRecord {
13	  taskId: string;
14	  title: string;
15	  description?: string;
16	  status: TaskStatus;
17	  screenshotUrl?: string | null;
18	  approvalStatus: TaskApprovalStatus;
19	  createdAt: string;
20	  updatedAt: string;
21	}
22	
23	/** Remove tasks that are complete+approved (or complete+rework with feedback submitted) past the grace period */
24	function autoCleanTasks(tasks: TaskRecord[]): TaskRecord[] {
25	  const now = Date.now();
26	  return tasks.filter((t) => {
27	    // Only auto-clear complete tasks that have been approved
28	    if (t.status === 'complete' && t.approvalStatus === 'approved') {
29	      const updatedMs = new Date(t.updatedAt).getTime();
30	      return now - updatedMs < AUTO_CLEAR_DELAY_MS;
31	    }
32	    return true;
33	  });
34	}
35	
36	async function readTasks(): Promise<TaskRecord[]> {
37	  try {
38	    await fs.access(TASKS_FILE);
39	    const raw = await fs.readFile(TASKS_FILE, 'utf-8');
40	    const parsed = JSON.parse(raw);
41	    const tasks: TaskRecord[] = Array.isArray(parsed.tasks) ? parsed.tasks : [];
42	    // Auto-clean on every read
43	    const cleaned = autoCleanTasks(tasks);
44	    if (cleaned.length !== tasks.length) {
45	      await writeTasks(cleaned);
46	    }
47	    return cleaned;
48	  } catch {
49	    return [];
50	  }
51	}
52	
53	async function writeTasks(tasks: TaskRecord[]) {
54	  await fs.writeFile(TASKS_FILE, JSON.stringify({ tasks }, null, 2), 'utf-8');
55	}
56	
57	export async function GET() {
58	  try {
59	    const tasks = await readTasks();
60	    return NextResponse.json({ tasks });
61	  } catch {
62	    return NextResponse.json({ error: 'Failed to read tasks' }, { status: 500 });
63	  }
64	}
65	
66	export async function POST(req: Request) {
67	  try {
68	    const body = await req.json();
69	    const { action, taskId } = body;
70	    if (!action || !taskId) return NextResponse.json({ error: 'Missing action or taskId' }, { status: 400 });
71	
72	    const tasks = await readTasks();
73	    const now = new Date().toISOString();
74	    const idx = tasks.findIndex(t => t.taskId === taskId);
75	
76	    if (action === 'update') {
77	      const { title, description, status, screenshotUrl } = body;
78	      if (idx === -1) {
79	        tasks.unshift({ taskId, title: title || taskId, description: description || '', status: status || 'pending', screenshotUrl: screenshotUrl || null, approvalStatus: 'pending', createdAt: now, updatedAt: now });
80	      } else {
81	        tasks[idx] = { ...tasks[idx], title: title || tasks[idx].title, description: description !== undefined ? description : tasks[idx].description, status: status || tasks[idx].status, screenshotUrl: screenshotUrl !== undefined ? screenshotUrl : tasks[idx].screenshotUrl, updatedAt: now };
82	      }
83	    } else if (action === 'approve' || action === 'reject') {
84	      if (idx === -1) return NextResponse.json({ error: 'Task not found' }, { status: 404 });
85	      tasks[idx] = { ...tasks[idx], approvalStatus: action === 'approve' ? 'approved' : 'rework', updatedAt: now };
86	    }
87	
88	    await writeTasks(tasks);
89	    return NextResponse.json({ ok: true, tasks });
90	  } catch {
91	    return NextResponse.json({ error: 'Failed' }, { status: 500 });
92	  }
93	}
