1	"use client";
2	
3	import { useState, useEffect } from "react";
4	import type { Task, TaskStatus } from "../types";
5	import { formatDuration, formatTokens } from "../types";
6	
7	// ── Status icon mapping ──
8	const STATUS_ICONS: Record<TaskStatus, string> = {
9	  running: "⚙️",
10	  done: "✅",
11	  failed: "❌",
12	};
13	
14	interface TaskCardProps {
15	  task: Task;
16	  expanded: boolean;
17	  onToggleExpanded: () => void;
18	  onDismiss: () => void;
19	}
20	
21	export function TaskCard({ task, expanded, onToggleExpanded, onDismiss }: TaskCardProps) {
22	  // Live duration ticker for running tasks
23	  const [, setTick] = useState(0);
24	  useEffect(() => {
25	    if (task.status !== "running") return;
26	    const id = setInterval(() => setTick((t) => t + 1), 1000);
27	    return () => clearInterval(id);
28	  }, [task.status]);
29	
30	  const showDismiss = task.requiresAcknowledgment && (task.status === "done" || task.status === "failed");
31	
32	  return (
33	    <div style={styles.card}>
34	      {/* ── Header row: icon + name + info button ── */}
35	      <div style={styles.header}>
36	        <span style={styles.statusIcon}>{STATUS_ICONS[task.status]}</span>
37	        <span style={styles.taskName}>{task.name}</span>
38	        <button
39	          onClick={onToggleExpanded}
40	          style={styles.infoButton}
41	          title={expanded ? "Hide details" : "Show details"}
42	          aria-label="Toggle task details"
43	        >
44	          ℹ️
45	        </button>
46	      </div>
47	
48	      {/* ── Description ── */}
49	      {task.description && (
50	        <div style={styles.description}>{task.description}</div>
51	      )}
52	
53	      {/* ── Expandable details panel ── */}
54	      {expanded && (
55	        <div style={styles.details}>
56	          {task.model && <DetailRow label="Agents" value={task.model} />}
57	          <DetailRow label="Started" value={new Date(task.startedAt).toLocaleTimeString()} />
58	          <DetailRow label="Duration" value={formatDuration(task.startedAt)} />
59	          {task.source && <DetailRow label="Source" value={task.source} />}
60	          {task.tokens != null && <DetailRow label="Tokens" value={formatTokens(task.tokens)} />}
61	          <DetailRow label="Status" value={task.status === "running" ? "Running..." : task.status === "done" ? "Complete" : "Failed"} />
62	          {task.sessionId && <DetailRow label="Session" value={task.sessionId} />}
63	          {task.meta &&
64	            Object.entries(task.meta).map(([k, v]) => (
65	              <DetailRow key={k} label={k} value={v} />
66	            ))}
67	        </div>
68	      )}
69	
70	      {/* ── Dismiss actions (only for tasks requiring acknowledgment) ── */}
71	      {showDismiss && (
72	        <div style={styles.actions}>
73	          <button onClick={onDismiss} style={styles.dismissButton}>
74	            ✓ Dismiss
75	          </button>
76	        </div>
77	      )}
78	    </div>
79	  );
80	}
81	
82	function DetailRow({ label, value }: { label: string; value: string }) {
83	  return (
84	    <div style={styles.detailRow}>
85	      <span style={styles.detailLabel}>{label}:</span>
86	      <span style={styles.detailValue}>{value}</span>
87	    </div>
88	  );
89	}
90	
91	// ── Inline styles (dark theme, matching recovery page aesthetic) ──
92	const styles: Record<string, React.CSSProperties> = {
93	  card: {
94	    background: "#141414",
